const workflowContext = this;
const env = $env || {};
const inputJson = (() => {
  try {
    const first = $input.first();
    return first && first.json ? first.json : {};
  } catch (error) {
    return {};
  }
})();

const requestBody = (inputJson && typeof inputJson.body === 'object' && inputJson.body !== null) ? inputJson.body : inputJson;

function required(value, name) {
  if (value === undefined || value === null || String(value).trim() === '') {
    throw new Error(`${name} is required`);
  }
  return value;
}

function trimSlash(value) {
  return String(value || '').replace(/\/+$/, '');
}

function toDateKey(dateObj) {
  const year = dateObj.getUTCFullYear();
  const month = String(dateObj.getUTCMonth() + 1).padStart(2, '0');
  const day = String(dateObj.getUTCDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function dateRangeUtc(dt) {
  const [y, m, d] = dt.split('-').map((v) => Number(v));
  const start = new Date(Date.UTC(y, m - 1, d, 0, 0, 0));
  const end = new Date(Date.UTC(y, m - 1, d, 23, 59, 59));
  return { start, end };
}

function toMinutes(start, end) {
  if (!start || !end) return null;
  const diff = (end.getTime() - start.getTime()) / 60000;
  return Number.isFinite(diff) ? diff : null;
}

function percentile(values, p) {
  const list = values.filter((v) => Number.isFinite(v)).sort((a, b) => a - b);
  if (!list.length) return null;
  const idx = Math.ceil((p / 100) * list.length) - 1;
  return list[Math.max(0, Math.min(idx, list.length - 1))];
}

function asDate(value) {
  if (!value) return null;
  const d = new Date(value);
  return Number.isFinite(d.getTime()) ? d : null;
}

function pickDeployedAt(deployment) {
  return asDate(deployment.finished_at)
    || asDate(deployment.updated_at)
    || asDate(deployment.created_at)
    || null;
}

function extractSha(deployment) {
  return deployment.sha
    || deployment.commit?.id
    || deployment.commit?.sha
    || deployment.deployable?.commit?.id
    || deployment.deployable?.commit?.sha
    || deployment.deployable?.pipeline?.sha
    || deployment.deployable?.pipeline?.commit?.id
    || null;
}

const realm = String(env.N8N_REALM || 'default').trim() || 'default';

const gitlabBaseUrl = trimSlash(
  requestBody.N8N_GITLAB_BASE_URL ||
  requestBody.GITLAB_BASE_URL ||
  requestBody.gitlab_base_url ||
  env.N8N_GITLAB_BASE_URL ||
  env.GITLAB_BASE_URL ||
  env.GITLAB_URL ||
  env.SERVICE_URL_GITLAB ||
  ''
);

const gitlabApiBase = trimSlash(
  requestBody.N8N_GITLAB_API_BASE_URL ||
  requestBody.GITLAB_API_BASE_URL ||
  requestBody.gitlab_api_base_url ||
  env.N8N_GITLAB_API_BASE_URL ||
  env.GITLAB_API_BASE_URL ||
  (gitlabBaseUrl ? `${gitlabBaseUrl}/api/v4` : '') ||
  ''
);

const gitlabToken = env.N8N_GITLAB_TOKEN || env.GITLAB_TOKEN || env.GITLAB_ADMIN_TOKEN || '';

let projectRef = (
  requestBody.N8N_GITLAB_PROJECT_ID ||
  requestBody.GITLAB_PROJECT_ID ||
  requestBody.N8N_GITLAB_PROJECT_PATH ||
  requestBody.GITLAB_PROJECT_PATH ||
  requestBody.gitlab_project_path ||
  env.N8N_GITLAB_PROJECT_ID ||
  env.GITLAB_PROJECT_ID ||
  env.N8N_GITLAB_PROJECT_PATH ||
  env.GITLAB_PROJECT_PATH ||
  ''
);
if (!projectRef) {
  projectRef = `${realm}/technical-management`;
}

const environmentName = String(env.N8N_GITLAB_ENVIRONMENT || 'production').trim() || 'production';
const deploymentsMaxPages = Number(env.N8N_GITLAB_DEPLOYMENTS_MAX_PAGES || '20');

required(gitlabApiBase, 'GITLAB_API_BASE_URL');
required(gitlabToken, 'GITLAB_TOKEN');
required(projectRef, 'GITLAB_PROJECT_ID or GITLAB_PROJECT_PATH');

const s3Bucket = env.N8N_S3_BUCKET || env.S3_BUCKET || '';
const s3Prefix = String(env.N8N_S3_PREFIX || 'itsm/technical_management').replace(/\/+$/, '');
required(s3Bucket, 'N8N_S3_BUCKET');

const targetDate = String(
  requestBody.N8N_METRICS_TARGET_DATE ||
  requestBody.target_date ||
  env.N8N_METRICS_TARGET_DATE ||
  ''
).trim();

let dt = '';
if (targetDate) {
  dt = targetDate;
} else {
  const now = new Date();
  const utcMidnightToday = new Date(Date.UTC(
    now.getUTCFullYear(),
    now.getUTCMonth(),
    now.getUTCDate(),
    0,
    0,
    0
  ));
  const utcMidnightYesterday = new Date(utcMidnightToday.getTime() - 24 * 60 * 60 * 1000);
  dt = toDateKey(utcMidnightYesterday);
}

if (!/^\d{4}-\d{2}-\d{2}$/.test(dt)) {
  throw new Error('target_date must be YYYY-MM-DD');
}

const { start, end } = dateRangeUtc(dt);

async function fetchAll(url, qs, maxPages) {
  const perPage = 100;
  let page = 1;
  const all = [];
  while (page <= maxPages) {
    const data = await workflowContext.helpers.httpRequest({
      method: 'GET',
      url,
      qs: {
        per_page: perPage,
        page,
        ...qs
      },
      json: true,
      headers: { 'PRIVATE-TOKEN': gitlabToken }
    });

    if (!Array.isArray(data)) break;
    all.push(...data);
    if (data.length < perPage) break;
    page += 1;
  }
  return all;
}

const projectEncoded = encodeURIComponent(projectRef);

// 1) Merge request lead time (created_at -> merged_at) for MRs merged within dt.
let mergedMrs = [];
try {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/merge_requests`;
  const list = await fetchAll(url, {
    state: 'merged',
    updated_after: start.toISOString(),
    scope: 'all',
    order_by: 'updated_at',
    sort: 'asc'
  }, 20);

  mergedMrs = list.filter((mr) => {
    const mergedAt = asDate(mr.merged_at);
    return mergedAt && mergedAt >= start && mergedAt <= end;
  });
} catch (error) {
  mergedMrs = [];
}

const mrLeadMinutes = mergedMrs
  .map((mr) => toMinutes(asDate(mr.created_at), asDate(mr.merged_at)))
  .filter((v) => v !== null);

// 2) Deployment-based lead time (merged_at -> deployed_at) for successful deployments within dt.
let deployments = [];
try {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/deployments`;
  deployments = await fetchAll(url, {
    environment: environmentName,
    updated_after: start.toISOString(),
    order_by: 'updated_at',
    sort: 'asc'
  }, Number.isFinite(deploymentsMaxPages) ? deploymentsMaxPages : 20);
} catch (error) {
  deployments = [];
}

const deploymentsInRange = deployments.filter((d) => {
  const deployedAt = pickDeployedAt(d);
  return deployedAt && deployedAt >= start && deployedAt <= end;
});

const successDeployments = deploymentsInRange.filter((d) => String(d.status || '').toLowerCase() === 'success');
const failedDeployments = deploymentsInRange.filter((d) => String(d.status || '').toLowerCase() === 'failed');

const changeFailureRate = (successDeployments.length + failedDeployments.length) > 0
  ? failedDeployments.length / (successDeployments.length + failedDeployments.length)
  : null;

const shaCache = new Map();

async function resolveMergedAtBySha(sha) {
  if (!sha) return null;
  if (shaCache.has(sha)) return shaCache.get(sha);
  let mergedAt = null;
  try {
    const url = `${gitlabApiBase}/projects/${projectEncoded}/repository/commits/${encodeURIComponent(sha)}/merge_requests`;
    const mrs = await workflowContext.helpers.httpRequest({
      method: 'GET',
      url,
      qs: { per_page: 20 },
      json: true,
      headers: { 'PRIVATE-TOKEN': gitlabToken }
    });
    if (Array.isArray(mrs)) {
      const merged = mrs
        .map((mr) => ({ mr, mergedAt: asDate(mr.merged_at) }))
        .filter((x) => x.mergedAt)
        .sort((a, b) => a.mergedAt.getTime() - b.mergedAt.getTime());
      if (merged.length) {
        mergedAt = merged[merged.length - 1].mergedAt;
      }
    }
  } catch (error) {
    mergedAt = null;
  }
  shaCache.set(sha, mergedAt);
  return mergedAt;
}

const deployLeadMinutes = [];
const deploymentEvents = [];

for (const d of successDeployments) {
  const deployedAt = pickDeployedAt(d);
  const sha = extractSha(d);
  const mergedAt = await resolveMergedAtBySha(sha);
  const minutes = toMinutes(mergedAt, deployedAt);
  if (minutes !== null) deployLeadMinutes.push(minutes);

  deploymentEvents.push({
    event_type: 'deployment',
    event_at: (deployedAt ? deployedAt.toISOString() : null),
    realm,
    gitlab_project_path: String(projectRef),
    environment: environmentName,
    deployment_id: d.id ?? null,
    deployment_status: d.status ?? null,
    deployed_at: d.finished_at || d.updated_at || d.created_at || null,
    sha: sha || null,
    merged_at: mergedAt ? mergedAt.toISOString() : null,
    lead_time_minutes: minutes,
    deployment_url: d.web_url || d.url || null
  });
}

const mrEvents = mergedMrs.map((mr) => {
  const mergedAt = asDate(mr.merged_at);
  const createdAt = asDate(mr.created_at);
  const minutes = toMinutes(createdAt, mergedAt);
  return {
    event_type: 'merge_request',
    event_at: mr.merged_at,
    realm,
    gitlab_project_path: String(projectRef),
    mr_iid: mr.iid ?? null,
    mr_id: mr.id ?? null,
    mr_title: mr.title ?? null,
    mr_url: mr.web_url || mr.url || null,
    created_at: mr.created_at,
    merged_at: mr.merged_at,
    lead_time_minutes: minutes
  };
});

const metrics = {
  realm,
  environment: environmentName,
  deployment_frequency: successDeployments.length,
  deployments_success_count: successDeployments.length,
  deployments_failed_count: failedDeployments.length,
  change_failure_rate: changeFailureRate,
  merge_requests_merged_count: mergedMrs.length,
  lead_time_for_changes_deploy_p50_minutes: percentile(deployLeadMinutes, 50),
  lead_time_for_changes_deploy_p95_minutes: percentile(deployLeadMinutes, 95),
  lead_time_for_changes_mr_p50_minutes: percentile(mrLeadMinutes, 50),
  lead_time_for_changes_mr_p95_minutes: percentile(mrLeadMinutes, 95)
};

metrics.lead_time_for_changes_p50_minutes = metrics.lead_time_for_changes_deploy_p50_minutes ?? metrics.lead_time_for_changes_mr_p50_minutes;
metrics.lead_time_for_changes_p95_minutes = metrics.lead_time_for_changes_deploy_p95_minutes ?? metrics.lead_time_for_changes_mr_p95_minutes;
metrics.lead_time_for_changes_source = (metrics.lead_time_for_changes_deploy_p50_minutes !== null && metrics.lead_time_for_changes_deploy_p50_minutes !== undefined)
  ? 'merge_to_deploy'
  : 'mr_created_to_merged';

const events = [...deploymentEvents, ...mrEvents];

const eventsBody = events.map((item) => JSON.stringify(item)).join('\n') + (events.length ? '\n' : '');
const metricsBody = JSON.stringify(metrics);

const eventsKey = `${s3Prefix}/dora/events/dt=${dt}/realm=${realm}/gitlab_dora_events.jsonl`;
const metricsKey = `${s3Prefix}/dora/daily_metrics/dt=${dt}/realm=${realm}/metrics.json`;

return [
  {
    json: {
      record_type: 'events',
      s3_bucket: s3Bucket,
      s3_key: eventsKey,
      dt,
      realm
    },
    binary: {
      data: {
        data: Buffer.from(eventsBody, 'utf8').toString('base64'),
        mimeType: 'application/json',
        fileName: 'gitlab_dora_events.jsonl'
      }
    }
  },
  {
    json: {
      record_type: 'daily_metrics',
      s3_bucket: s3Bucket,
      s3_key: metricsKey,
      dt,
      realm
    },
    binary: {
      data: {
        data: Buffer.from(metricsBody, 'utf8').toString('base64'),
        mimeType: 'application/json',
        fileName: 'metrics.json'
      }
    }
  }
];
